                    <label>Doelgroepplaats<input type="text" value={draft.locationQuery ?? "Zoetermeer"} onChange={(event) => updateAdDraft("locationQuery", event.target.value)} placeholder="Bijvoorbeeld Zoetermeer" /></label>
